const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to calculate NDVI for Landsat 8/9
function addNDVI_L8(image) {
  const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  return image.addBands(ndvi);
}

// Helper function to calculate NDVI for Landsat 5/7
function addNDVI_L57(image) {
  const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
  return image.addBands(ndvi);
}

// Helper function to mask clouds, shadows, and water for Landsat 8/9 C2 L2
function maskL8sr(image) {
  // Bit 3 is cloud, bit 4 is cloud shadow.
  const cloudShadowBitMask = (1 << 3);
  const cloudsBitMask = (1 << 4);
  const qa = image.select('QA_PIXEL');
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  return image.updateMask(mask);
}

// Helper function to mask clouds, shadows, and water for Landsat 4/5/7 C2 L2
function maskL457sr(image) {
  // Bit 5 is cloud, bit 3 is cloud shadow.
  const cloudShadowBitMask = (1 << 3);
  const cloudsBitMask = (1 << 5);
  const qa = image.select('QA_PIXEL');
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  return image.updateMask(mask);
}

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Rectangle([14.4, -23.05, 14.6, -22.85]); // Walvis Bay, Namibia

    // 2. Data Acquisition & Processing for 2021
    const col2021_l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(region)
        .filterDate('2021-02-01', '2021-02-28')
        .map(maskL8sr)
        .map(addNDVI_L8)
        .select('NDVI');

    if (col2021_l8.size().getInfo() === 0) {
        console.log("No Landsat 8 images found for Feb 2021.");
        console.log("A: Yes"); // No data to compare against, so baseline is not exceeded.
        return;
    }

    const mean2021 = col2021_l8.mean();

    // 3. Data Acquisition & Processing for Baseline (2010-2020)
    const col_l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(region)
        .filter(ee.Filter.calendarRange(2, 2, 'month'))
        .filterDate('2010-01-01', '2011-12-31') // L5 active until late 2011
        .map(maskL457sr)
        .map(addNDVI_L57)
        .select('NDVI');

    const col_l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterBounds(region)
        .filter(ee.Filter.calendarRange(2, 2, 'month'))
        .filterDate('2010-01-01', '2020-12-31')
        .map(maskL457sr)
        .map(addNDVI_L57)
        .select('NDVI');

    const col_l8_base = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(region)
        .filter(ee.Filter.calendarRange(2, 2, 'month'))
        .filterDate('2013-04-01', '2020-12-31') // L8 starts 2013
        .map(maskL8sr)
        .map(addNDVI_L8)
        .select('NDVI');

    const baselineCol = ee.ImageCollection(col_l5.merge(col_l7).merge(col_l8_base));

    if (baselineCol.size().getInfo() === 0) {
        console.log("No baseline images found for Feb 2010-2020.");
        console.log("C1: Empty Collection");
        return;
    }

    const meanBaseline = baselineCol.mean();

    // 4. Calculation & Validation
    const scale = 1000;
    const commonReducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats2021 = mean2021.reduceRegion({
        reducer: commonReducer,
        geometry: region,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const statsBaseline = meanBaseline.reduceRegion({
        reducer: commonReducer,
        geometry: region,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const ndvi2021 = stats2021['NDVI_mean'];
    const pixels2021 = stats2021['NDVI_count'];

    const ndviBaseline = statsBaseline['NDVI_mean'];
    const pixelsBaseline = statsBaseline['NDVI_count'];

    // Check for C2: No Valid Pixels
    if (!pixels2021 || !pixelsBaseline || pixels2021 === 0 || pixelsBaseline === 0) {
        console.log(`Valid Pixels 2021: ${pixels2021 || 0}`);
        console.log(`Valid Pixels Baseline: ${pixelsBaseline || 0}`);
        console.log("C2: No Valid Pixels");
        return;
    }

    // Check for C3: Calculation Failure
    if (ndvi2021 === null || ndviBaseline === null || isNaN(ndvi2021) || isNaN(ndviBaseline)) {
        console.log(`NDVI 2021: ${ndvi2021}`);
        console.log(`NDVI Baseline: ${ndviBaseline}`);
        console.log("C3: Calculation Failure");
        return;
    }

    // 5. Final Answer
    console.log(`Feb 2021 Avg NDVI: ${ndvi2021.toFixed(4)} (Pixels: ${pixels2021})`);
    console.log(`Feb 2010-2020 Avg NDVI: ${ndviBaseline.toFixed(4)} (Pixels: ${pixelsBaseline})`);
    console.log(`Image Count 2021: ${col2021_l8.size().getInfo()}`);
    console.log(`Image Count Baseline: ${baselineCol.size().getInfo()}`);

    if (ndvi2021 > ndviBaseline) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
  }
}

initEE();
